"use client";

/**
 * Personalised drills generated by Claude in the browser.
 *
 * The site is a static export with no backend, so, like the Riot sync in the
 * tracker, the call goes straight from the browser to the Claude API with a
 * key the player pastes in (kept in localStorage, never sent anywhere else).
 * The model gets the player's weak categories, their recent misses, the live
 * set's unit/item catalogue and the exact scenario schema, and returns drills
 * that are validated with the same Zod schema the build uses before any of
 * them is shown. Anything that fails validation is dropped, so a hallucinated
 * id can never reach the board.
 */
import Anthropic from "@anthropic-ai/sdk";
import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
import { z } from "zod";
import { ScenarioSchema, type Scenario } from "./scenario-schema";
import { CATEGORY_LABELS, SCENARIO_CATEGORIES, type ScenarioCategory } from "./scenario-categories";
import type { UnitLookup, ItemLookup } from "./set-data";
import { readJson, safeGet, safeRemove, safeSet, writeJson } from "./storage";

export const AI_KEY = "tftlab.ai.key.v1";
export const AI_DRILLS_KEY = "tftlab.ai-drills.v1";
export const AI_MODEL = "claude-opus-5";

export interface AiDrillSet {
  version: 1;
  generatedAt: string;
  focus: ScenarioCategory[];
  drills: Scenario[];
}

export function readApiKey(): string | null {
  return safeGet(AI_KEY);
}
export function writeApiKey(key: string): boolean {
  return key ? safeSet(AI_KEY, key.trim()) : (safeRemove(AI_KEY), true);
}

export function readAiDrills(): AiDrillSet | null {
  const d = readJson<AiDrillSet | null>(AI_DRILLS_KEY, null);
  return d && d.version === 1 && Array.isArray(d.drills) ? d : null;
}
export function writeAiDrills(set: AiDrillSet | null): boolean {
  return set ? writeJson(AI_DRILLS_KEY, set) : (safeRemove(AI_DRILLS_KEY), true);
}

/** What the generator needs to know about the player; assembled by the UI from the trainer progress. */
export interface PlayerContext {
  /** weakest first, with accuracy 0..1 and attempts */
  weak: { category: ScenarioCategory; accuracy: number; attempts: number }[];
  /** a few recently missed drills: prompt + principle, so the new ones attack the same gaps */
  misses: { category: ScenarioCategory; prompt: string; principle: string }[];
  /** 1..4 rank tier the player is training at */
  tier: 1 | 2 | 3 | 4;
  /** extra wishes typed by the player, optional */
  request?: string;
}

/** Catalogue handed to the model: ids it may use, nothing else. */
export interface Catalogue {
  setNumber: number;
  units: Record<string, UnitLookup>;
  items: Record<string, ItemLookup>;
  traitNames: Record<string, string>;
  guideAnchors: string[];
}

const Output = z.object({
  drills: z.array(z.unknown()).min(1).max(8),
});

function catalogueText(cat: Catalogue): string {
  const units = Object.values(cat.units)
    .filter((u) => !u.id.startsWith("generic:"))
    .sort((a, b) => a.cost - b.cost || a.name.localeCompare(b.name))
    .map((u) => `${u.cost} ${u.id} "${u.name}" [${u.traits.map((t) => cat.traitNames[t] ?? t).join("/")}]${u.ability ? ` — ${u.ability.name}: ${u.ability.desc.replace(/\s+/g, " ").slice(0, 160)}` : ""}`)
    .join("\n");
  const items = Object.values(cat.items)
    .filter((i) => !i.id.startsWith("generic:"))
    .map((i) => `${i.kind} ${i.id} "${i.name}"`)
    .join("\n");
  return `LIVE SET CHAMPIONS (cost id "name" [traits] — ability):\n${units}\n\nLIVE SET ITEMS (kind id "name"):\n${items}`;
}

const SYSTEM = `You are a Challenger-level Teamfight Tactics coach writing decision drills for TFT Lab, a training site. Each drill is one concrete board state and one question with a single defensible best answer, graded automatically. You write for one specific player and attack the exact gaps in their play. Sound like a coach: direct, concrete, arithmetic where it matters (interest, odds, HP counts), no fluff.

You output JSON only, matching the schema you are given, with real ids from the catalogue and nothing invented. A drill that names an id not in the catalogue is thrown away, so double-check every championId, itemId and augment id.`;

const SCHEMA_TEXT = `SCENARIO JSON (one object per drill):
{
  "id": "ai-<kebab-slug>" (unique),
  "category": one of ${SCENARIO_CATEGORIES.join(" | ")},
  "difficulty": 1 | 2 | 3 | 4 (1 Iron–Silver, 2 Gold–Platinum, 3 Emerald–Diamond, 4 Master+),
  "kind": "drill",
  "setAgnostic": false, "set": <setNumber>,
  "prompt": "2–4 sentences: the situation with stage/gold/HP/level, ending with the question",
  "state": {
    "stage": "3-2" (digit-digit), "gold": int, "hp": 1..100, "level": 1..10, "xpToNext": int,
    "streak": { "type": "win"|"loss", "count": int },
    "board": [ { "championId": "<catalogue id>", "row": 0..3, "col": 0..6, "star": 1|2|3, "items": ["<item id>", ...max 3] } ],  (row 0 = FRONT line, row 3 = BACK line; odd rows shift half a hex right; no two units on one hex; board.length <= level)
    "bench": [ { "championId": "<id>", "star": 1, "items": [], "slot": 0..8 } ] (max 9),
    "shop": [exactly 5 entries, each "<champion id>" or null],
    "items": ["<component/item id>", ...] (inventory),
    "enemyBoard": [ same shape as board, optional ],
    "lobby": [ { "player": "Seat 2", "hp": int, "note": "what they play" }, ... ] (optional)
  },
  "question": ONE of
    { "type": "choice", "options": [{ "id": "a", "label": "..." }, ... 3–4], "correct": ["a"] }
    { "type": "placement", "unitId": "<id>", "correctHexes": [{ "row": r, "col": c }, ...] }  (unit starts on the bench: board.length must be < level and every correct hex empty)
    { "type": "swap", "correctPairs": [["<id on board>", "<id on board>"]] }  (every championId on the board must be unique)
    { "type": "item-holder", "itemId": "<item id>", "correctUnitIds": ["<id on board>"] }
    { "type": "ordering", "steps": ["...", ... 4–6], "correctOrder": [permutation of 0..n-1] },
  "explanation": "400–900 chars, markdown paragraphs: why the answer is right AND why the tempting wrong option is wrong, with the arithmetic",
  "principle": "one memorable sentence",
  "guideLink": one of the allowed guide links,
  "commonMistake": "one sentence",
  "hint": "20–260 chars: what to look at or count, never the answer"
}`;

function userPrompt(ctx: PlayerContext, cat: Catalogue, n: number): string {
  const weak = ctx.weak.length ? ctx.weak.map((w) => `- ${CATEGORY_LABELS[w.category]} (${w.category}): ${Math.round(w.accuracy * 100)}% over ${w.attempts} drills`).join("\n") : "- (no data yet: pick a spread of fundamentals)";
  const misses = ctx.misses.length ? ctx.misses.map((m) => `- [${m.category}] ${m.prompt.slice(0, 220)} → principle: ${m.principle}`).join("\n") : "- (none recorded)";
  return `PLAYER
Training tier: ${ctx.tier} (write at this difficulty).
Weakest categories (attack these; at least two thirds of the drills go to the top two):
${weak}
Recently missed drills (write NEW situations that test the same principle from a different angle; do not copy them):
${misses}
${ctx.request ? `Player's own request: ${ctx.request}\n` : ""}
TASK
Write ${n} drills for this player. Vary the question types (at least one board question: placement, swap or item-holder). Use the live set's real champions and items from the catalogue below, and only facts about abilities that appear in the catalogue text. Every drill must be self-contained and solvable from the prompt plus the board.

${SCHEMA_TEXT}

ALLOWED guideLink values:
${cat.guideAnchors.join("\n")}

${catalogueText(cat)}

Return {"drills": [ ...${n} scenario objects... ]}.`;
}

export interface GenerateResult {
  drills: Scenario[];
  /** validation failures, one line each (for the "n dropped" note) */
  dropped: string[];
  usage: { input: number; output: number };
}

export async function generateDrills(apiKey: string, ctx: PlayerContext, cat: Catalogue, n = 5, signal?: AbortSignal): Promise<GenerateResult> {
  const client = new Anthropic({ apiKey, dangerouslyAllowBrowser: true, maxRetries: 1 });
  const stream = client.messages.stream(
    {
      model: AI_MODEL,
      max_tokens: 32000,
      system: SYSTEM,
      messages: [{ role: "user", content: userPrompt(ctx, cat, n) }],
      output_config: { format: zodOutputFormat(Output), effort: "high" },
    },
    { signal },
  );
  const message = await stream.finalMessage();
  if (message.stop_reason === "refusal") throw new Error("The model declined this request.");
  if (message.stop_reason === "max_tokens") throw new Error("The response was cut off; try fewer drills.");
  const text = message.content.find((b): b is Anthropic.TextBlock => b.type === "text")?.text ?? "";
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new Error("The model returned something that is not JSON.");
  }
  const parsed = Output.safeParse(raw);
  if (!parsed.success) throw new Error("The model returned an unexpected shape.");
  const { drills, dropped } = filterDrills(parsed.data.drills, cat);
  return { drills, dropped, usage: { input: message.usage.input_tokens, output: message.usage.output_tokens } };
}


/** Keep only drills that pass the site schema and use ids from the catalogue; pure, tested. */
export function filterDrills(list: unknown[], cat: Catalogue): { drills: Scenario[]; dropped: string[] } {
  const known = (id: string) => id in cat.units || id in cat.items;
  const drills: Scenario[] = [];
  const dropped: string[] = [];
  const seen = new Set<string>();
  list.forEach((d, i) => {
    const r = ScenarioSchema.safeParse(d);
    if (!r.success) {
      dropped.push(`drill ${i + 1}: ${r.error.issues[0]?.path.join(".")} ${r.error.issues[0]?.message}`);
      return;
    }
    const s = r.data;
    if (s.setAgnostic || s.set !== cat.setNumber) {
      dropped.push(`drill ${i + 1}: not written for the live set`);
      return;
    }
    const ids = [
      ...s.state.board.map((u) => u.championId),
      ...s.state.bench.map((u) => u.championId),
      ...(s.state.enemyBoard ?? []).map((u) => u.championId),
      ...s.state.shop.filter((x): x is string => !!x),
      ...s.state.items,
      ...s.state.board.flatMap((u) => u.items),
      ...(s.question.type === "placement" ? [s.question.unitId] : []),
      ...(s.question.type === "item-holder" ? [s.question.itemId] : []),
    ];
    const bad = ids.find((id) => !known(id));
    if (bad) {
      dropped.push(`drill ${i + 1}: unknown id ${bad}`);
      return;
    }
    if (s.question.type === "augment") {
      dropped.push(`drill ${i + 1}: augment questions are not supported here`);
      return;
    }
    if (!cat.guideAnchors.includes(s.guideLink)) s.guideLink = cat.guideAnchors[0]!;
    let id = s.id.startsWith("ai-") ? s.id : `ai-${s.id}`;
    while (seen.has(id)) id = `${id}-2`;
    seen.add(id);
    drills.push({ ...s, id });
  });
  return { drills, dropped };
}

/** Rough cost of one generation at list price, for the note under the button. */
export function estimateCost(usage: { input: number; output: number }): number {
  return (usage.input * 5 + usage.output * 25) / 1_000_000;
}

export function describeError(e: unknown): string {
  if (e instanceof Anthropic.AuthenticationError) return "The API key was rejected. Check it in the box above.";
  if (e instanceof Anthropic.RateLimitError) return "Rate limited by the API; wait a minute and try again.";
  if (e instanceof Anthropic.BadRequestError) return `The request was rejected: ${e.message}`;
  if (e instanceof Anthropic.APIConnectionError) return "Could not reach the API (network, ad blocker or CORS).";
  if (e instanceof Anthropic.APIError) return `API error ${e.status}: ${e.message}`;
  if (e instanceof Error) return e.message;
  return "Something went wrong.";
}
